--[[
  SteamBackdrop (steambackdrop) — Lua 后端
  职责：
  1. 扫描插件 media 目录下的图片/视频，以及 Wallpaper Engine 壁纸（工坊订阅 + 本地项目）；
  2. 读取媒体内容并转 base64 dataURL 供前端显示/设为壁纸（大文件分块传输）；
  3. 读写 settings.json 持久化用户选择（壁纸/透明度/范围/启用）。
  前端通过 Millennium.callServerMethod("steambackdrop", "方法名", "json字符串") 调用。
]]

local millennium = require("millennium")
local json = require("json")
local logger = require("logger")
local fs = require("fs")
local utils = require("utils")
logger:info("[SteamBackdrop] backend script started")

local PLUGIN_NAME = "steambackdrop"
local IMAGE_EXTS = {
  [".png"] = "image/png",
  [".jpg"] = "image/jpeg",
  [".jpeg"] = "image/jpeg",
  [".webp"] = "image/webp",
  [".bmp"] = "image/bmp",
  [".gif"] = "image/gif",
}
local VIDEO_EXTS = {
  [".mp4"] = "video/mp4",
  [".webm"] = "video/webm",
  [".m4v"] = "video/mp4",
  [".mov"] = "video/quicktime",
}
-- 分块传输的单块上限（视频不走整体 base64，逐块读拼 Blob）
local CHUNK_BYTES = 1024 * 1024
local MAX_IMAGE_BYTES = 10 * 1024 * 1024

local function mime_of(path)
  local ext = tostring(path):match("(%.%w+)$")
  if not ext then return nil end
  ext = ext:lower()
  return IMAGE_EXTS[ext] or VIDEO_EXTS[ext]
end

local B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

--- 纯算术 base64 编码（不用位运算符，兼容任何 Lua 版本）
---@param data string
---@return string
local function b64encode(data)
  local out, n = {}, #data
  for i = 1, n, 3 do
    local a, b, c = data:byte(i, i + 2)
    local v = a * 65536 + (b or 0) * 256 + (c or 0)
    local c1 = math.floor(v / 262144) % 64
    local c2 = math.floor(v / 4096) % 64
    local c3 = math.floor(v / 64) % 64
    local c4 = v % 64
    out[#out + 1] =
      B64:sub(c1 + 1, c1 + 1) ..
      B64:sub(c2 + 1, c2 + 1) ..
      (b and B64:sub(c3 + 1, c3 + 1) or "=") ..
      (c and B64:sub(c4 + 1, c4 + 1) or "=")
  end
  return table.concat(out)
end

local B64DEC = {}
for i = 1, 64 do
  B64DEC[B64:sub(i, i)] = i - 1
end

--- base64 解码（容错：忽略空白，遇非法字符返回 nil）
---@param s string
---@return string|nil
local function b64decode(s)
  if type(s) ~= "string" then return nil end
  local out, buf, nbits = {}, 0, 0
  for i = 1, #s do
    local ch = s:sub(i, i)
    if ch ~= "=" and ch ~= "\r" and ch ~= "\n" and ch ~= " " then
      local v = B64DEC[ch]
      if not v then return nil end
      buf = buf * 64 + v
      nbits = nbits + 6
      if nbits >= 8 then
        nbits = nbits - 8
        out[#out + 1] = string.char(math.floor(buf / (2 ^ nbits)) % 256)
        buf = buf % (2 ^ nbits)
      end
    end
  end
  return table.concat(out)
end

--- 清洗字符串：把无效 UTF-8 字节替换为 "?"，避免 C++ 层 json 解析崩溃
---@param s any
---@return any
local function utf8safe(s)
  if type(s) ~= "string" then return s end
  local out, i, n = {}, 1, #s
  while i <= n do
    local b = s:byte(i)
    if b < 0x80 then
      out[#out + 1] = string.char(b)
      i = i + 1
    elseif b < 0xC0 then
      out[#out + 1] = "?"
      i = i + 1
    elseif b < 0xE0 then
      local b1 = s:byte(i + 1)
      if b1 and b1 >= 0x80 and b1 < 0xC0 and i + 1 <= n then
        out[#out + 1] = s:sub(i, i + 1)
        i = i + 2
      else
        out[#out + 1] = "?"
        i = i + 1
      end
    elseif b < 0xF0 then
      local b1, b2 = s:byte(i + 1, i + 2)
      if b1 and b2 and b1 >= 0x80 and b1 < 0xC0 and b2 >= 0x80 and b2 < 0xC0 and i + 2 <= n then
        out[#out + 1] = s:sub(i, i + 2)
        i = i + 3
      else
        out[#out + 1] = "?"
        i = i + 1
      end
    elseif b < 0xF8 then
      local b1, b2, b3 = s:byte(i + 1, i + 3)
      if b1 and b2 and b3 and b1 >= 0x80 and b1 < 0xC0 and b2 >= 0x80 and b2 < 0xC0
          and b3 >= 0x80 and b3 < 0xC0 and i + 3 <= n then
        out[#out + 1] = s:sub(i, i + 3)
        i = i + 4
      else
        out[#out + 1] = "?"
        i = i + 1
      end
    else
      out[#out + 1] = "?"
      i = i + 1
    end
  end
  return table.concat(out)
end

-- GBK -> UTF-8 转换表（由 Python 从 GBK 编码生成，126×190 项，3 字节大端码点/项）
-- Millennium 的 fs.list 在中文 Windows 上返回 ANSI(GBK) 字节，显示前需转换。
local GBK_B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local GBK_DEC = {}
for i = 1, 64 do GBK_DEC[GBK_B64:sub(i, i)] = i - 1 end
local DATA_B64 = ""
local function gbk_b64d(s)
  local out, buf, nbits = {}, 0, 0
  for i = 1, #s do
    local ch = s:sub(i, i)
    if ch ~= "=" and ch ~= "\r" and ch ~= "\n" and ch ~= " " then
      local v = GBK_DEC[ch]
      if not v then return nil end
      buf = buf * 64 + v
      nbits = nbits + 6
      if nbits >= 8 then
        nbits = nbits - 8
        out[#out + 1] = string.char(math.floor(buf / (2 ^ nbits)) % 256)
        buf = buf % (2 ^ nbits)
      end
    end
  end
  return table.concat(out)
end
local DATA = assert(gbk_b64d(DATA_B64), "gbk table corrupt")
assert(#DATA == 126 * 190 * 3, "gbk table size mismatch")

--- 把 GBK(ANSI) 字节串转成 UTF-8；已是 ASCII 的部分原样保留，无法映射的字节变 "?"
---@param s string
---@return string
local function toutf8(s)
  if type(s) ~= "string" then return s end
  local out, i, n = {}, 1, #s
  while i <= n do
    local b = s:byte(i)
    if b < 0x80 then
      out[#out + 1] = string.char(b)
      i = i + 1
    elseif b >= 0x81 and b <= 0xFE and i + 1 <= n then
      local t = s:byte(i + 1)
      if (t >= 0x40 and t <= 0x7E) or (t >= 0x80 and t <= 0xFE) then
        local ti = t < 0x80 and (t - 0x40) or (t - 0x41)
        local off = ((b - 0x81) * 190 + ti) * 3
        local cp = DATA:byte(off + 1) * 65536 + DATA:byte(off + 2) * 256 + DATA:byte(off + 3)
        if cp == 0xFFFF or cp == 0 then
          out[#out + 1] = "?"
        elseif cp < 0x800 then
          out[#out + 1] = string.char(0xC0 + math.floor(cp / 64), 0x80 + cp % 64)
        else
          out[#out + 1] = string.char(0xE0 + math.floor(cp / 4096), 0x80 + (math.floor(cp / 64) % 64), 0x80 + (cp % 64))
        end
        i = i + 2
      else
        out[#out + 1] = "?"
        i = i + 1
      end
    else
      out[#out + 1] = "?"
      i = i + 1
    end
  end
  return table.concat(out)
end

local gbk = { toutf8 = toutf8 }

--- 显示名清洗：fs.list 在中文 Windows 返回 GBK 字节，先转 UTF-8 再兜底清洗
---@param s any
---@return any
local function disp(s)
  if type(s) ~= "string" then return s end
  return utf8safe(gbk.toutf8(s))
end

local function as_array(t)
  return setmetatable(t or {}, { __jsontype = "array" })
end

local function entry_name(e)
  if type(e) == "string" then return e end
  if type(e) == "table" then
    if type(e.name) == "string" then return e.name end
    if type(e.filename) == "string" then return e.filename end
    if type(e[1]) == "string" then return e[1] end
  end
  return nil
end

local function plugin_dir()
  local steam = millennium.steam_path()
  if not steam or steam == "" then return nil end
  return fs.join(steam, "millennium", "plugins", PLUGIN_NAME)
end

local function media_dir()
  local d = plugin_dir()
  return d and fs.join(d, "media") or nil
end

local function settings_file()
  local d = plugin_dir()
  return d and fs.join(d, "settings.json") or nil
end

--[[ Wallpaper Engine 支持 ]]

local WE_PREVIEW_NAMES = { "preview.gif", "preview.jpg", "preview.jpeg", "preview.png", "preview.webp" }

--- 解析 steamapps/libraryfolders.vdf，枚举所有 Steam 库路径（学 mayflyTheme：
--- 壁纸可能装在非主库的其他 Steam 库盘里，不能只扫 steam_path() 一处）
---@return string[]
local function steam_libraries()
  local steam = millennium.steam_path()
  if not steam or steam == "" then return {} end
  local libs = { tostring(steam) }
  local vdf = fs.join(fs.join(tostring(steam), "steamapps"), "libraryfolders.vdf")
  local f = io.open(vdf, "rb")
  if f then
    local content = f:read("*a")
    f:close()
    if content then
      local main = tostring(steam):lower():gsub("/", "\\")
      for rawp in content:gmatch('"path"%s*"([^"]*)"') do
        local p = rawp:gsub("\\\\", "\\")
        local norm = p:lower():gsub("/", "\\")
        if norm:sub(-1) == "\\" then norm = norm:sub(1, -2) end
        if p ~= "" and norm ~= main then
          libs[#libs + 1] = p
        end
      end
    end
  end
  return libs
end

--- Wallpaper Engine 壁纸容器根目录：每个 Steam 库的工坊订阅项 +
--- wallpaper_engine 安装位置的官方示例 / 用户项目
--- （每个根的直接子目录就是一张壁纸项目，内含 preview.* 与 project.json）
local function we_roots()
  local roots, seen = {}, {}
  local function add(p)
    if p and p ~= "" then
      local k = tostring(p):lower():gsub("/", "\\")
      if not seen[k] then
        seen[k] = true
        roots[#roots + 1] = p
      end
    end
  end
  for _, lib in ipairs(steam_libraries()) do
    local apps = fs.join(lib, "steamapps")
    add(fs.join(fs.join(fs.join(apps, "workshop"), "content"), "431960"))
    local we_projects = fs.join(fs.join(fs.join(apps, "common"), "wallpaper_engine"), "projects")
    add(fs.join(we_projects, "defaultprojects"))
    add(fs.join(we_projects, "myprojects"))
  end
  return roots
end

--- 判断 path 是否位于 root 之下（大小写不敏感，统一按 \ 比较）
local function path_under(path, root)
  if not path or not root then return false end
  local p = tostring(path):lower():gsub("/", "\\")
  local r = tostring(root):lower():gsub("/", "\\")
  if r:sub(-1) ~= "\\" then r = r .. "\\" end
  return p:sub(1, #r) == r
end

--- 从 project.json 里轻量提取 title（正则即可，避免整文件解析）
local function read_title(dir)
  local f = io.open(fs.join(dir, "project.json"), "rb")
  if not f then return nil end
  local s = f:read("*a")
  f:close()
  if not s then return nil end
  local t = s:match('"title"%s*:%s*"([^"]*)"')
  if t and t ~= "" then return t end
  return nil
end

--- 在目录（含一层子目录）里找最大的指定类型文件
---@param dir string
---@param exts table<string,string>
---@param skip_prefix? string 跳过此前缀开头的文件名（如 preview）
---@return string|nil path, number|nil size
local function find_largest(dir, exts, skip_prefix)
  local best, best_size = nil, -1
  local function scan_dir(d, depth)
    if depth > 1 then return end
    local ok, list = pcall(fs.list, d)
    if not ok or type(list) ~= "table" then return end
    for _, e in ipairs(list) do
      local name = entry_name(e)
      if name then
        local base = name:match("([^\\/]+)$")
        if base then
          local p = fs.join(d, base)
          if fs.is_directory(p) then
            scan_dir(p, depth + 1)
          else
            local ext = base:match("(%.%w+)$")
            local mime = ext and exts[ext:lower()] or nil
            if mime and not (skip_prefix and base:lower():sub(1, #skip_prefix) == skip_prefix) then
              local f = io.open(p, "rb")
              if f then
                local n = f:seek("end")
                f:close()
                n = n or 0
                if n > best_size then
                  best_size = n
                  best = p
                end
              end
            end
          end
        end
      end
    end
  end
  scan_dir(dir, 0)
  if best then return best, best_size end
  return nil, nil
end

--- 扫描 Wallpaper Engine 壁纸。
--- 只用真实内容文件，不再用 preview 糊图：
---   - 项目内有视频文件（mp4/webm/...）→ kind=video，应用视频本体
---   - 有 scene.pkg 且没有视频 → 交互式场景壁纸，无法静态呈现，跳过不显示
---   - 否则取项目里最大的非 preview 图片 → kind=image（清晰度优先）
local function scan_we()
  local out = {}
  for _, root in ipairs(we_roots()) do
    if fs.is_directory(root) then
      local ok, list = pcall(fs.list, root)
      if ok and type(list) == "table" then
        for _, e in ipairs(list) do
          local dirname = entry_name(e)
          if dirname then
            local base = dirname:match("([^\\/]+)$")
            if base then
              local dir = fs.join(root, base)
              if fs.is_directory(dir) then
                local video, vsize = find_largest(dir, VIDEO_EXTS)
                local applied, asize, kind
                if video then
                  applied, asize, kind = video, vsize, "video"
                else
                  -- scene.pkg = 交互式场景（shader/粒子），无视频文件的不显示
                  local scene_pkg = fs.join(dir, "scene.pkg")
                  if not fs.is_file(scene_pkg) then
                    applied, asize = find_largest(dir, IMAGE_EXTS, "preview")
                    if applied then kind = "image" end
                  end
                end
                if applied and kind then
                  local t = read_title(dir)
                  table.insert(out, {
                    token = "w:" .. b64encode(applied),
                    title = t and utf8safe(t) or disp(base),
                    kind = kind,
                    size = asize,
                    folder = disp(base),
                  })
                end
              end
            end
          end
        end
      end
    end
  end
  table.sort(out, function(a, b) return tostring(a.title) < tostring(b.title) end)
  return out
end

--- 扫描 Wallpaper Engine 壁纸（返回 JSON 字符串）
---@return string
function ScanWallpaperEngine()
  local ok, result = pcall(function()
    local roots = we_roots()
    local walls = scan_we()
    logger:info("[SteamBackdrop] WE scan: " .. #walls .. " wallpaper(s) from " .. #roots .. " root(s)")
    for i, r in ipairs(roots) do
      logger:info("[SteamBackdrop]   root[" .. i .. "] " .. disp(r) .. " exists=" .. tostring(fs.is_directory(r)))
    end
    return { ok = true, wallpapers = as_array(walls), roots = as_array(roots) }
  end)
  if not ok then
    return json.encode({ ok = false, error = utf8safe(tostring(result)), wallpapers = as_array({}) })
  end
  return json.encode(result)
end

--- 解析壁纸引用：返回 {path=..., err=...}；引用格式（token 均为 base64，避免非 UTF-8 文件名崩溃）：
---   "m:<b64(文件名)>"     media 目录图片
---   "w:<b64(绝对路径)>"   Wallpaper Engine 预览图（必须在允许目录下）
---   "<纯文件名>"          旧格式兼容：按 media 文件名处理
local function resolve_ref(name)
  if type(name) ~= "string" or name == "" then
    return { err = "bad name" }
  end
  local kind = name:sub(1, 2)
  if kind == "m:" or kind == "w:" then
    local raw = b64decode(name:sub(3))
    if not raw then return { err = "bad token" } end
    if kind == "m:" then
      if raw:find("[/\\\\]") or raw:find("%.%." ) then return { err = "bad name" } end
      local dir = media_dir()
      if not dir then return { err = "no media dir" } end
      local p = fs.join(dir, raw)
      if not fs.is_file(p) then return { err = "not found" } end
      return { path = p }
    end
    local allowed = path_under(raw, media_dir())
    if not allowed then
      for _, root in ipairs(we_roots()) do
        if path_under(raw, root) then allowed = true break end
      end
    end
    if not allowed then return { err = "path not allowed" } end
    if not fs.is_file(raw) then return { err = "not found" } end
    return { path = raw }
  end
  if name:find("[/\\\\]") or name:find("%.%." ) then
    return { err = "bad name" }
  end
  local dir = media_dir()
  if not dir then return { err = "no media dir" } end
  local p = fs.join(dir, name)
  if not fs.is_file(p) then return { err = "not found" } end
  return { path = p }
end

--- 扫描 media 目录下的图片和视频（排序后的数组，元素含 name/size/kind/token）
local function scan()
  local files = {}
  local dir = media_dir()
  if not dir or not fs.is_directory(dir) then return files end
  local ok, list = pcall(fs.list, dir)
  if not ok or type(list) ~= "table" then return files end
  for _, e in ipairs(list) do
    local name = entry_name(e)
    if name then
      local base = name:match("([^\\/]+)$") or name
      local mime = mime_of(base)
      if mime then
        local p = fs.join(dir, base)
        if fs.is_file(p) then
          local f = io.open(p, "rb")
          local size = 0
          if f then
            local n = f:seek("end")
            size = n or 0
            f:close()
          end
          local kind = VIDEO_EXTS[tostring(base):match("(%.%w+)$"):lower()] and "video" or "image"
          table.insert(files, { token = "m:" .. b64encode(base), name = disp(base), size = size, kind = kind, mime = mime })
        end
      end
    end
  end
  table.sort(files, function(a, b) return tostring(a.name) < tostring(b.name) end)
  return files
end

--- 扫描媒体目录（返回 JSON 字符串）
---@return string
function ScanWallpapers()
  local ok, files = pcall(scan)
  if not ok then
    return json.encode({ ok = false, error = utf8safe(tostring(files)), files = as_array({}), mediaDir = tostring(media_dir()) })
  end
  return json.encode({ ok = true, files = as_array(files), mediaDir = tostring(media_dir()) })
end

--- 读取媒体信息（类型/大小），供前端分块拉取
---@param name string|table
---@return string
function GetMediaInfo(name)
  if type(name) == "table" then name = name.name or name[1] end
  local ok, result = pcall(function()
    local ref = resolve_ref(name)
    if ref.err then return { ok = false, error = ref.err } end
    local mime = mime_of(ref.path)
    if not mime then return { ok = false, error = "unsupported type" } end
    local f = io.open(ref.path, "rb")
    if not f then return { ok = false, error = "cannot open" } end
    local size = f:seek("end") or 0
    f:close()
    local kind = VIDEO_EXTS[tostring(ref.path):match("(%.%w+)$"):lower()] and "video" or "image"
    return { ok = true, kind = kind, mime = mime, size = size }
  end)
  if not ok then
    return json.encode({ ok = false, error = utf8safe(tostring(result)) })
  end
  return json.encode(result)
end

--- 分块读取媒体内容（base64）。offset/len 由前端控制，单块上限 CHUNK_BYTES
---@param name string|table
---@param offset number|table
---@param len number?
---@return string
function GetMediaChunk(name, offset, len)
  if type(name) == "table" then
    -- Millennium 把对象参数作为单张表传入：{name=..., offset=..., len=...}
    local t = name
    name, offset, len = t.name or t[1], t.offset or t[2], t.len or t[3]
  end
  offset = tonumber(offset) or 0
  len = tonumber(len) or CHUNK_BYTES
  if len < 1 or len > CHUNK_BYTES then len = CHUNK_BYTES end
  local ok, result = pcall(function()
    local ref = resolve_ref(name)
    if ref.err then return { ok = false, error = ref.err } end
    local f = io.open(ref.path, "rb")
    if not f then return { ok = false, error = "cannot open" } end
    f:seek("set", offset)
    local data = f:read(len)
    f:close()
    if not data then return { ok = false, error = "read failed" } end
    return { ok = true, offset = offset, b64 = b64encode(data) }
  end)
  if not ok then
    return json.encode({ ok = false, error = utf8safe(tostring(result)) })
  end
  return json.encode(result)
end

--- 读取图片为 dataURL（上限 MAX_IMAGE_BYTES，仅适合小图快路径）
---@param name string|table
---@return string
function GetImageData(name)
  if type(name) == "table" then name = name.name or name[1] end
  local ok, result = pcall(function()
    local ref = resolve_ref(name)
    if ref.err then return { ok = false, error = ref.err } end
    local f = io.open(ref.path, "rb")
    if not f then return { ok = false, error = "cannot open: " .. tostring(name) } end
    local data = f:read("*a")
    f:close()
    if not data then return { ok = false, error = "read failed" } end
    local size = #data
    local ext = tostring(ref.path):match("(%.%w+)$")
    local mime = (ext and IMAGE_EXTS[ext:lower()]) or "image/png"
    if size > MAX_IMAGE_BYTES then
      return { ok = false, error = "too_large", size = size, mime = mime }
    end
    return { ok = true, dataUrl = "data:" .. mime .. ";base64," .. b64encode(data), size = size, mime = mime }
  end)
  if not ok then
    return json.encode({ ok = false, error = tostring(result) })
  end
  return json.encode(result)
end

local DEFAULTS = { name = "", dim = "0", scope = "home", enabled = true, details = true, other = false }

local function read_settings()
  local s = { name = DEFAULTS.name, dim = DEFAULTS.dim, scope = DEFAULTS.scope, enabled = DEFAULTS.enabled, details = DEFAULTS.details, other = DEFAULTS.other }
  local path = settings_file()
  if path and fs.exists(path) then
    local content = utils.read_file(path)
    if content then
      local d = json.decode(content)
      if type(d) == "table" then
        if type(d.name) == "string" then s.name = d.name end
        if type(d.dim) == "string" then s.dim = d.dim end
        if d.scope == "gamepage" or d.scope == "home" then s.scope = d.scope end
        if type(d.enabled) == "boolean" then s.enabled = d.enabled end
        if type(d.details) == "boolean" then s.details = d.details end
        if type(d.other) == "boolean" then s.other = d.other end
      end
    end
  end
  return s
end

--- 读取设置（返回 JSON 字符串）
---@return string
function GetSettings()
  local ok, s = pcall(read_settings)
  if not ok then
    return json.encode({ name = DEFAULTS.name, dim = DEFAULTS.dim, scope = DEFAULTS.scope, enabled = DEFAULTS.enabled, details = DEFAULTS.details, other = DEFAULTS.other })
  end
  return json.encode(s)
end

--- 保存设置（兼容多种调用形式）：
---   SaveSettings(json字符串)          — 前端传 [JSON.stringify(payload)]
---   SaveSettings(table)               — 参数以对象形式整体传入
---   SaveSettings(name, dim, scope, enabled) — 多参数形式
---@return string
function SaveSettings(...)
  local args = { ... }
  local ok, result = pcall(function()
    local d = nil
    if #args == 1 and type(args[1]) == "string" and args[1] ~= "" then
      d = json.decode(args[1])
    elseif #args == 1 and type(args[1]) == "table" then
      d = args[1]
    elseif #args >= 4 then
      d = { name = args[1], dim = args[2], scope = args[3], enabled = args[4] }
    end
    if type(d) ~= "table" then
      return { ok = false, error = "bad payload (got " .. #args .. " args, first=" .. type(args[1]) .. ")" }
    end

    local s = read_settings()
    if type(d.name) == "string" then s.name = d.name end
    if type(d.dim) == "string" then s.dim = d.dim end
    if d.scope == "gamepage" or d.scope == "home" then s.scope = d.scope end
    if type(d.enabled) == "boolean" then s.enabled = d.enabled end
    if type(d.details) == "boolean" then s.details = d.details end
    if type(d.other) == "boolean" then s.other = d.other end

    if s.name ~= "" then
      local ref = resolve_ref(s.name)
      if ref.err then
        return { ok = false, error = "壁纸不存在: " .. utf8safe(s.name) }
      end
    end

    local path = settings_file()
    if not path then
      return { ok = false, error = "no plugin dir" }
    end
    local f = io.open(path, "w")
    if not f then
      return { ok = false, error = "cannot write settings.json" }
    end
    f:write(json.encode(s))
    f:close()

    logger:info("[SteamBackdrop] settings saved: name='" .. s.name .. "' dim=" .. s.dim .. " scope=" .. s.scope .. " enabled=" .. tostring(s.enabled))
    return { ok = true }
  end)
  if not ok then
    return json.encode({ ok = false, error = tostring(result) })
  end
  return json.encode(result)
end

---@return string
function Ping()
  return json.encode({ ok = true, plugin = PLUGIN_NAME, version = "1.0.0" })
end

local function on_load()
  local ok, err = pcall(function()
    local files = scan()
    logger:info("[SteamBackdrop] loaded, " .. #files .. " wallpaper(s) in media dir")
  end)
  if not ok then
    logger:error("[SteamBackdrop] on_load scan failed: " .. tostring(err))
  end
  millennium.ready()
end

local function on_frontend_loaded()
  logger:info("[SteamBackdrop] frontend loaded")
end

local function on_unload()
  logger:info("[SteamBackdrop] unloaded")
end

--- 前端诊断日志（写入插件日志，便于确认前端已执行）
---@param text string
---@return string
function LogDiag(text)
  pcall(function()
    logger:info("[SteamBackdrop][diag] " .. tostring(text))
  end)
  return json.encode({ ok = true })
end

return {
  on_load = on_load,
  on_frontend_loaded = on_frontend_loaded,
  on_unload = on_unload,
}
